-- V2__seed.sql — MediCare Pharmacy seed data (PostgreSQL)
--
-- Demo credentials (password for ALL three users is literally: password):
--   admin@medicare.com      / password  (ADMIN)
--   pharmacist@medicare.com / password  (PHARMACIST)
--   customer@medicare.com   / password  (CUSTOMER)
--
-- Password hash below is a BCrypt cost-10 hash for "password" generated by
-- this project's own BCryptPasswordEncoder (verified live on 2026-09-21).
--   $2a$10$1Ft7Cjk0H0VHJqPqtmukeua8ZLF2nvg5dK1WboVCHCt8EhZ0Xy8fi
-- Spring Security BCryptPasswordEncoder.matches("password", <hash>) == true.

-- ================= categories =================
ON CONFLICT (name) DO NOTHING;

-- ================= users =================
-- All passwords = "password" (BCrypt cost 10, see header comment).
ON CONFLICT (email) DO NOTHING;

-- ================= medicines (8 rows) =================
ON CONFLICT DO NOTHING;

-- ================= inventory =================
-- One item (Cetirizine 10mg, quantity 3) is deliberately low-stock (<= reorder_level 10)
-- to demo the low-stock alert.
ON CONFLICT (medicine_id) DO NOTHING;
